const arroz = 24.9;
const feijao = 8.75;
const oleo = 7.49;
const percentual = 5;

// converta os preços para centavos aqui

// calcule o subtotal, o desconto e o total em centavos

// mostre os três valores em reais

exercises.solution:
const arroz = 24.9;
const feijao = 8.75;
const oleo = 7.49;
const percentual = 5;

const arrozCentavos = Math.round(arroz * 100);
const feijaoCentavos = Math.round(feijao * 100);
const oleoCentavos = Math.round(oleo * 100);

const subtotalCentavos = arrozCentavos + feijaoCentavos + oleoCentavos;
const descontoCentavos = Math.round(subtotalCentavos * percentual / 100);
const totalCentavos = subtotalCentavos - descontoCentavos;

console.log('Subtotal: R$', (subtotalCentavos / 100).toFixed(2));
console.log('Desconto: R$', (descontoCentavos / 100).toFixed(2));
console.log('Total: R$', (totalCentavos / 100).toFixed(2));
